    use core.http;
    use core.proc;
    use core.thread;

    async fn bounded_http() -> i32 {
        timeout(25)
        let conn = http.accept()
        defer close(conn)
        discard http.read(conn)
        return 0
    }

    async fn unbounded_http() -> i32 {
        let conn = http.accept()
        defer close(conn)
        discard http.read(conn)
        return 0
    }

    fn main() -> i32 {
        let env_map = proc.env_new()
        let argv = proc.argv_new()
