listener = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
listener.bind(('127.0.0.1', 0))
listener.listen(1)
port = listener.getsockname()[1]
def delayed_sse_server():
    conn, _ = listener.accept()
    with conn:
        conn.recv(4096)
        conn.sendall(b'HTTP/1.1 200 OK\r\nContent-Type: text/event-stream\r\nConnection: close\r\n\r\n')
        time.sleep(0.15)
        conn.sendall(b'event: message_start\n\n')
    listener.close()
thread = threading.Thread(target=delayed_sse_server)
thread.start()
stream_proj = write_project('http_stream_timeout_runtime', f'''
    use core.http;
    use core.thread;

    fn main() -> i32 {{
        discard http.header_set("accept", "text/event-stream")
        timeout(25)
        let stream = http.post_json_stream("http://127.0.0.1:{port}/sse", "{{\"stream\":true}}")
        defer http.stream_close(stream)
        if http.stream_status(stream) != 200 {{
            return http.stream_status(stream)
        }}
        let line = http.stream_read_line(stream)
        let err = http.stream_error(stream)
        if line == "" && (http.stream_eof(stream) == 1 || str.len(err) > 0) {{
            return 0
        }}
        return 17
    }}
''')
stream_proc = subprocess.run([str(fz), 'run', str(stream_proj), '--proc-backend', 'host', '--fs-backend', 'host', '--http-backend', 'host', '--json'], cwd=str(repo), capture_output=True, text=True)
thread.join(timeout=2)
stream_payload = json.loads(stream_proc.stdout.strip())
assert stream_proc.returncode == 0, (stream_proc.returncode, stream_payload, stream_proc.stderr)
